import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../styles/ManageUsers.css"; // Reuse or update if needed

const MyGigs = () => {
  const [gigs, setGigs] = useState([]);
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  const fetchGigs = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/gigs/my-gigs", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setGigs(response.data);
    } catch (err) {
      console.error("❌ Error fetching gigs:", err);
    }
  };

  const handleDelete = async (gigId) => {
    const confirmDelete = window.confirm("Are you sure you want to delete this gig?");
    if (!confirmDelete) return;

    try {
      await axios.delete(`http://localhost:5000/api/gigs/${gigId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      alert("✅ Gig deleted successfully");
      setGigs(prev => prev.filter(gig => gig._id !== gigId));
    } catch (err) {
      alert("❌ Could not delete gig");
    }
  };

  useEffect(() => {
    fetchGigs();
  }, []);

  return (
    <div className="manage-users-container">
      <h1 className="gig-page-title">MY GIGS</h1>

      <div className="gig-button-container">
        <button className="post-gig-btn" onClick={() => navigate("/post-gig")}>
          Post A New Gig
        </button>
      </div>

      <div className="user-list">
        {gigs.length > 0 ? (
          gigs.map((gig) => (
            <div key={gig._id} className="user-card gig-card">
              <span className="gig-title">{gig.title}</span>
              <div className="gig-actions">
                <button onClick={() => navigate(`/gig/${gig._id}`)}>View</button>
                <button onClick={() => navigate(`/edit-gig/${gig._id}`)}>Edit</button>
                <button onClick={() => handleDelete(gig._id)}>Delete</button>
              </div>
            </div>
          ))
        ) : (
          <p className="no-gigs-msg">You have not posted any gigs yet.</p>
        )}
      </div>
    </div>
  );
};

export default MyGigs;
